# Relational schema for SMMS. Column: (name, type, flags)  flags: PK, FK:table, NN, UQ, plus free text checks
T=[]
def t(name,sub,cols,notes=""): T.append(dict(name=name,sub=sub,cols=cols,notes=notes))
t("account","IAM",[("account_id","INT","PK"),("email","VARCHAR(255)","NN, UQ"),("password_hash","VARCHAR(255)","NN"),("role","VARCHAR(12)","NN, CHECK IN (Visitor, Staff, Manager, ITAdmin)"),("is_active","BOOLEAN","NN, DEFAULT true"),("email_verified","BOOLEAN","NN, DEFAULT false"),("mfa_enabled","BOOLEAN","NN, DEFAULT false"),("mfa_secret","VARCHAR(64)",""),("failed_login_count","INT","NN, DEFAULT 0"),("lock_until","TIMESTAMP","")],"One row per account; exactly one role (FR-04).")
t("visitor","IAM",[("visitor_id","INT","PK, FK→account"),("display_name","VARCHAR(100)","NN"),("mobile_number","VARCHAR(20)","encrypted (AES-256)"),("preferred_language","CHAR(2)","NN, CHECK IN (EN, AR)"),("text_size","VARCHAR(10)","NN, DEFAULT 'normal'"),("high_contrast","BOOLEAN","NN, DEFAULT false"),("consent_personalisation","BOOLEAN","NN, DEFAULT false"),("consent_withdrawn_at","TIMESTAMP","")])
t("staff","IAM",[("staff_id","INT","PK, FK→account"),("full_name","VARCHAR(100)","NN"),("department","VARCHAR(60)","")])
t("manager","IAM",[("manager_id","INT","PK, FK→account"),("full_name","VARCHAR(100)","NN")])
t("it_admin","IAM",[("admin_id","INT","PK, FK→account")])
t("verification_token","IAM",[("token_hash","CHAR(64)","PK"),("account_id","INT","NN, FK→account"),("purpose","VARCHAR(16)","NN, CHECK IN (verify_email, reset_password)"),("expires_at","TIMESTAMP","NN"),("used_at","TIMESTAMP","")],"Single-use links; reset links expire after 30 minutes (FR-05).")
t("category","COL",[("category_id","INT","PK"),("name","VARCHAR(60)","NN, UQ")])
t("interest_profile","REC",[("profile_id","INT","PK"),("visitor_id","INT","NN, UQ, FK→visitor"),("updated_at","TIMESTAMP","NN")])
t("profile_category","REC",[("profile_id","INT","PK, FK→interest_profile"),("category_id","INT","PK, FK→category")],"Resolves InterestProfile.categories (many-to-many).")
t("artifact","COL",[("artifact_id","INT","PK"),("title","VARCHAR(200)","NN"),("category_id","INT","NN, FK→category"),("description","TEXT",""),("period","VARCHAR(80)",""),("origin","VARCHAR(80)",""),("condition","VARCHAR(10)","NN, CHECK IN (excellent, good, fair, poor)"),("location","VARCHAR(100)","NN"),("status","VARCHAR(20)","NN, CHECK IN (onDisplay, inStorage, onLoan, underRestoration)"),("dimensions","VARCHAR(80)",""),("acquisition_details","TEXT",""),("image_url","VARCHAR(255)",""),("inspection_date","DATE",""),("is_archived","BOOLEAN","NN, DEFAULT false"),("archive_reason","VARCHAR(255)",""),("qr_code_value","VARCHAR(64)","NN, UQ"),("rfid_tag_id","VARCHAR(64)","UQ"),("created_by","INT","NN, FK→staff"),("updated_by","INT","FK→staff"),("updated_at","TIMESTAMP","NN")],"Never physically deleted (FR-10); version checked on update (E3 of UC-12).")
t("condition_report","COL",[("report_id","INT","PK"),("artifact_id","INT","NN, FK→artifact"),("rating","VARCHAR(10)","NN, CHECK IN (excellent, good, fair, poor)"),("notes","TEXT",""),("reported_by","INT","NN, FK→staff"),("reported_at","TIMESTAMP","NN")])
t("status_history","COL",[("history_id","INT","PK"),("artifact_id","INT","NN, FK→artifact"),("field_name","VARCHAR(40)","NN"),("old_value","VARCHAR(255)",""),("new_value","VARCHAR(255)",""),("changed_by","INT","NN, FK→staff"),("changed_at","TIMESTAMP","NN")],"Append-only history log (FR-09, FR-14).")
t("exhibition","COL",[("exhibition_id","INT","PK"),("title","VARCHAR(200)","NN"),("gallery","VARCHAR(80)","NN"),("start_date","DATE","NN"),("end_date","DATE","NN, CHECK end_date ≥ start_date"),("description","TEXT","")])
t("exhibition_item","COL",[("exhibition_id","INT","PK, FK→exhibition"),("artifact_id","INT","PK, FK→artifact"),("display_start_date","DATE","NN"),("display_end_date","DATE","NN")],"Association class ExhibitionItem (many-to-many).")
t("time_slot","TKT",[("slot_id","INT","PK"),("exhibition_id","INT","NN, FK→exhibition"),("slot_date","DATE","NN"),("start_time","TIME","NN"),("end_time","TIME","NN"),("capacity","INT","NN, CHECK capacity > 0"),("confirmed_seats","INT","NN, DEFAULT 0, CHECK 0 ≤ confirmed_seats ≤ capacity")],"UNIQUE (exhibition_id, slot_date, start_time). Row is locked (SELECT … FOR UPDATE) during the capacity check (NFR-12).")
t("ticket_type","TKT",[("ticket_type_id","INT","PK"),("exhibition_id","INT","NN, FK→exhibition"),("name","VARCHAR(50)","NN"),("price","NUMERIC(8,2)","NN, CHECK price ≥ 0"),("per_booking_limit","INT","NN, DEFAULT 10")],"UNIQUE (exhibition_id, name).")
t("booking","TKT",[("booking_id","INT","PK"),("booking_reference","VARCHAR(16)","NN, UQ"),("visitor_id","INT","NN, FK→visitor"),("slot_id","INT","NN, FK→time_slot"),("ticket_type_id","INT","NN, FK→ticket_type"),("quantity","INT","NN, CHECK quantity > 0"),("total_price","NUMERIC(10,2)","NN"),("status","VARCHAR(10)","NN, CHECK IN (pending, confirmed, cancelled, completed)"),("created_at","TIMESTAMP","NN")])
t("seat_hold","TKT",[("hold_id","INT","PK"),("booking_id","INT","NN, UQ, FK→booking"),("slot_id","INT","NN, FK→time_slot"),("quantity","INT","NN, CHECK quantity > 0"),("expires_at","TIMESTAMP","NN"),("status","VARCHAR(10)","NN, CHECK IN (active, converted, expired, released)")],"Persists the 10-minute hold (FR-19): remaining = capacity − confirmed_seats − SUM(quantity of active holds).")
t("payment_record","TKT",[("payment_id","INT","PK"),("booking_id","INT","NN, UQ, FK→booking"),("gateway_status","VARCHAR(20)","NN"),("amount","NUMERIC(10,2)","NN"),("currency","CHAR(3)","NN"),("transaction_ref","VARCHAR(64)","NN, UQ"),("paid_at","TIMESTAMP","")],"No card number, expiry or security code column exists (FR-20, NFR-18).")
t("digital_ticket","TKT",[("ticket_id","INT","PK"),("booking_id","INT","NN, FK→booking"),("token","VARCHAR(128)","NN, UQ"),("status","VARCHAR(10)","NN, CHECK IN (unused, used, cancelled, expired)"),("issued_at","TIMESTAMP","NN")],"QR image is generated from the signed token and is not stored.")
t("entry_validation","TKT",[("validation_id","INT","PK"),("ticket_id","INT","NN, FK→digital_ticket"),("staff_id","INT","NN, FK→staff"),("result","VARCHAR(8)","NN, CHECK IN (valid, rejected)"),("reason","VARCHAR(40)",""),("validated_at","TIMESTAMP","NN")],"Partial unique index on (ticket_id) WHERE result = 'valid' → a ticket is accepted only once (FR-24).")
t("live_visitor_counter","TKT",[("counter_date","DATE","PK"),("visitors_in","INT","NN, CHECK visitors_in ≥ 0"),("updated_at","TIMESTAMP","NN")],"Live visitor count shown to staff and management (FR-26).")
t("recommendation","REC",[("recommendation_id","INT","PK"),("visitor_id","INT","NN, FK→visitor"),("artifact_id","INT","NN, FK→artifact"),("rank","INT","NN, CHECK rank ≥ 1"),("reason","VARCHAR(255)","NN"),("shown_at","TIMESTAMP","NN"),("clicked","BOOLEAN","NN, DEFAULT false"),("dismissed","BOOLEAN","NN, DEFAULT false")])
t("feedback","REC",[("feedback_id","INT","PK"),("visitor_id","INT","NN, FK→visitor"),("artifact_id","INT","NN, FK→artifact"),("rating","INT","NN, CHECK rating BETWEEN 1 AND 5"),("comment","TEXT",""),("submitted_at","TIMESTAMP","NN")],"UNIQUE (visitor_id, artifact_id).")
t("knowledge_entry","REC",[("entry_id","INT","PK"),("artifact_id","INT","FK→artifact"),("question","VARCHAR(300)","NN"),("answer","TEXT","NN"),("language","CHAR(2)","NN, CHECK IN (EN, AR)"),("status","VARCHAR(12)","NN, CHECK IN (draft, published, unpublished)"),("source_page","VARCHAR(200)",""),("updated_by","INT","FK→staff"),("updated_at","TIMESTAMP","NN")],"Chatbot may use only status = 'published' (SPEC-4).")
t("chat_session","REC",[("session_id","INT","PK"),("visitor_id","INT","NN, FK→visitor"),("language","CHAR(2)","NN"),("started_at","TIMESTAMP","NN")],"Counters (questions, answered, fallbacks) are derived by view for FR-38.")
t("chat_turn","REC",[("turn_id","INT","PK"),("session_id","INT","NN, FK→chat_session"),("entry_id","INT","FK→knowledge_entry"),("question","TEXT","NN"),("answer","TEXT",""),("was_fallback","BOOLEAN","NN"),("created_at","TIMESTAMP","NN")],"entry_id is NULL for a fallback turn (FR-32).")
t("ar_content","AR",[("content_id","INT","PK"),("artifact_id","INT","NN, UQ, FK→artifact"),("model_url","VARCHAR(255)","NN"),("file_size_mb","NUMERIC(4,1)","NN, CHECK file_size_mb ≤ 20"),("overlay_text","TEXT",""),("published","BOOLEAN","NN, DEFAULT false"),("updated_at","TIMESTAMP","NN")])
t("ar_session","AR",[("ar_session_id","INT","PK"),("content_id","INT","NN, FK→ar_content"),("started_at","TIMESTAMP","NN"),("duration_seconds","INT",""),("device_type","VARCHAR(30)",""),("used_fallback","BOOLEAN","NN, DEFAULT false")],"Anonymised: no visitor column (FR-41).")
t("report_export","ANA",[("report_id","INT","PK"),("generated_by","INT","NN, FK→manager"),("period_start","DATE","NN"),("period_end","DATE","NN"),("filter_exhibition_id","INT","FK→exhibition"),("filter_ticket_type_id","INT","FK→ticket_type"),("format","VARCHAR(3)","NN, CHECK IN (PDF, CSV)"),("generated_at","TIMESTAMP","NN")],"Aggregated values are computed by queries/views; only the export metadata is stored.")
t("audit_log","AUD",[("log_id","INT","PK"),("event_type","VARCHAR(20)","NN, CHECK IN (login, failedLogin, roleChange, artifactChange, ticketValidation, accessDenied)"),("user_id","INT","FK→account"),("event_time","TIMESTAMP","NN"),("details","TEXT","")],"Retained ≥ 12 months (NFR-20); INDEX (event_time, event_type).")
t("notification","NTF",[("notification_id","INT","PK"),("account_id","INT","NN, FK→account"),("booking_id","INT","FK→booking"),("channel","VARCHAR(6)","NN, CHECK IN (email, sms, inApp)"),("type","VARCHAR(14)","NN, CHECK IN (confirmation, cancellation, reminder, passwordReset)"),("status","VARCHAR(8)","NN, CHECK IN (sent, failed, retrying)"),("attempts","INT","NN, DEFAULT 0"),("sent_at","TIMESTAMP","")])
SUBCOL={"IAM":"#e8d9f5","COL":"#fff0b3","TKT":"#cfe2ff","REC":"#d4edcf","AR":"#ffd9c2","ANA":"#f5d0d0","AUD":"#e0e0e0","NTF":"#d9f0f0"}
SUBNAME={"IAM":"Identity & Access","COL":"Collection & Exhibition","TKT":"Ticketing & Visitor Mgmt","REC":"Recommendation & Chatbot","AR":"AR Experience","ANA":"Analytics & Reporting","AUD":"Audit & Monitoring","NTF":"Notification"}
def fks():
    out=[]
    for tb in T:
        for c,ty,fl in tb["cols"]:
            if "FK→" in fl:
                parent=fl.split("FK→")[1].split(",")[0].strip()
                pk="PK" in fl.split("FK")[0]
                uq="UQ" in fl
                nn="NN" in fl or pk
                out.append((parent,tb["name"],c,pk,uq,nn))
    return out
if __name__=="__main__":
    print(len(T),len(fks()))
